/* From Uiverse.io by cssbuttons-io - Tags: button */
.__UIV_SCOPE__ .btn {
 position: relative;
 font-size: 17px;
 text-transform: uppercase;
 text-decoration: none;
 padding: 1em 2.5em;
 display: inline-block;
 border-radius: 6em;
 transition: all .2s;
 border: none;
 font-family: inherit;
 font-weight: 500;
 color: black;
 background-color: white;
}

.__UIV_SCOPE__ .btn:hover {
 transform: translateY(-3px);
 box-shadow: 0 10px 20px rgba(0, 0, 0, 0.2);
}

.__UIV_SCOPE__ .btn:active {
 transform: translateY(-1px);
 box-shadow: 0 5px 10px rgba(0, 0, 0, 0.2);
}

.__UIV_SCOPE__ .btn::after {
 content: "";
 display: inline-block;
 height: 100%;
 width: 100%;
 border-radius: 100px;
 position: absolute;
 top: 0;
 left: 0;
 z-index: -1;
 transition: all .4s;
}

.__UIV_SCOPE__ .btn::after {
 background-color: #fff;
}

.__UIV_SCOPE__ .btn:hover::after {
 transform: scaleX(1.4) scaleY(1.6);
 opacity: 0;
}
